+{
+	dawit_result result = DAWIT_FAIL;
+	log_data *current_log = NULL;
+	char *line_buffer = NULL;
+	int line_size = 0;
+
+	if (file == NULL)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "passed NUll file path");
+		return DAWIT_FAIL;
+	}
+
+	log_buffer_lock();
+	current_log = log_buffer_get_first();
+	SSMCodeInfo* codeInfo = SSM_ES_get_code_info();
+
+	while (current_log != NULL)
+	{
+
+		if (SSM_get_file_write_timeout())
+		{
+			DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "SSM file write timeout");
+			log_buffer_unlock();
+			return DAWIT_FAIL;
+		}
+
+		SSM_Log_Type logType = SSM_map_code_to_log_type(current_log->code[0]);
+
+		if (codeInfo[logType].SSM_status == DAWIT_TRUE && 
+			current_log->level >= codeInfo[logType].SSM_level)
+		{
+			line_size = SSM_MIN_LOG_BUFFER_SIZE + LOG_BUFFER_CODE_SIZE + (current_log->message ? strlen(current_log->message) : 0);
+			line_buffer = (char *)calloc(1, line_size);
+
+			if (line_buffer == NULL)
+			{
+				DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to allocate memory for line buffer");
+				log_buffer_unlock();
+				return DAWIT_FAIL;
+			}
+
+			/* Format the line: (0,time,code,message) */
+			if (current_log->message != NULL)
+			{
+				snprintf(line_buffer, line_size, "<0#%d#%s#%s>\n", current_log->time, current_log->code, current_log->message);
+			}
+			else
+			{
+				snprintf(line_buffer, line_size, "<0#%d#%s#>\n", current_log->time, current_log->code);
+			}
+
+			/* Write to file */
+			dawit_result write_result = SSM_file_write(file, (unsigned char *)line_buffer, strlen(line_buffer));
+			if (write_result != DAWIT_SUCCESS)
+			{
+				DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to write to file");
+				free(line_buffer);
+				line_buffer = NULL;
+				log_buffer_unlock();
+				return DAWIT_FAIL;
+			}
+			free(line_buffer);
+			line_buffer = NULL;
+		}
+		current_log = current_log->next;
+	}
+	log_buffer_unlock();
+	return DAWIT_SUCCESS;
+}
+
+
+static dawit_result SSM_write_SYS_logs_to_file(ssm_file *file)
+{
+	dawit_result result = DAWIT_FAIL;
+	KPI_data *KPI_table = NULL;
+	int size = 0;
+	SSM_SYS_code_info* sysCodeInfo = SSM_SYS_get_code_info();
+
+	if (file == NULL)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "passed NUll file path");
+		return DAWIT_FAIL;
+	}
+
+	KPI_buffer_lock();
+	KPI_table = KPI_get_table(&size);
+
+	if (KPI_table != NULL && size > 0)
+	{
+		/* Iterate through all KPI data */
+		for (int i = 0; i < size+1; i++)
+		{
+
+			if (SSM_get_file_write_timeout())
+			{
+				DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "SSM file write timeout");
+				KPI_buffer_unlock();
+				return DAWIT_FAIL;
+			}
+
+			/* Skip KPI data with NONE send type */
+			if (KPI_table[i].KPI_send_type == KPI_SEND_NONE || KPI_table[i].KPI_send_type == KPI_SEND_NOW || sysCodeInfo[KPI_table[i].KPI_tag].status != DAWIT_TRUE)
+			{
+				continue;
+			}
+
+			/* Allocate buffer for the line (sufficiently large) */
+			int kpi_line_size = SSM_MIN_KPI_BUFFER_SIZE + (KPI_table[i].KPI_name ? strlen(KPI_table[i].KPI_name) : 0) +
+							(KPI_table[i].KPI_message_str ? strlen(KPI_table[i].KPI_message_str) : 0);
+			char *kpi_line_buffer = (char *)calloc(1, kpi_line_size);
+			if (kpi_line_buffer == NULL)
+			{
+				DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to allocate memory for line buffer");
+				KPI_buffer_unlock();
+				return DAWIT_FAIL;
+			}
+
+			/* Format the line: (1,kpi_name,data_type,message) */
+			if (KPI_table[i].KPI_data_type == KPI_DATA_NUM)
+			{
+				snprintf(kpi_line_buffer, kpi_line_size, "<1#%s#%s#%d>\n",
+						 KPI_table[i].KPI_name ? KPI_table[i].KPI_name : "",
+						 kpi_data_type_to_string(KPI_table[i].KPI_data_type),
+						 KPI_table[i].KPI_message_num);
+			}
+			else if (KPI_table[i].KPI_data_type == KPI_DATA_STR)
+			{
+				snprintf(kpi_line_buffer, kpi_line_size, "<1#%s#%s#%s>\n",
+						 KPI_table[i].KPI_name ? KPI_table[i].KPI_name : "",
+						 kpi_data_type_to_string(KPI_table[i].KPI_data_type),
+						 KPI_table[i].KPI_message_str ? KPI_table[i].KPI_message_str : "");
+			}
+			else
+			{
+				/* Unknown data type, skip this entry */
+				free(kpi_line_buffer);
+				kpi_line_buffer = NULL;
+				continue;
+			}
+
+			/* Write to file */
+			dawit_result write_result = SSM_file_write(file, (unsigned char *)kpi_line_buffer, strlen(kpi_line_buffer));
+			if (write_result != DAWIT_SUCCESS)
+			{
+				DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to write to file");
+				free(kpi_line_buffer);
+				kpi_line_buffer = NULL;
+				KPI_buffer_unlock();
+				return DAWIT_FAIL;
+			}
+
+			free(kpi_line_buffer);
+			kpi_line_buffer = NULL;
+		}
+	}
+
+	/* Unlock the KPI buffer */
+	KPI_buffer_unlock();
+	return DAWIT_SUCCESS;
+}
+
+static dawit_result SSM_get_file_creation_time_imp(const char *file_path, time_t *creation_time)
+{
+	struct stat file_stat;
+
+	if (file_path == NULL || creation_time == NULL)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Invalid arguments: file_path=%p, creation_time=%p", file_path, creation_time);
+		return DAWIT_INVALID_ARGS;
+	}
+
+	if (stat(file_path, &file_stat) != 0)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to get file stats for %s", file_path);
+		return DAWIT_FAIL;
+	}
+
+	/* On Linux/Tizen, st_ctime is the closest to creation time available vi a stat().
+	 * It represents the time of last inode change (set at file creation). */
+	*creation_time = file_stat.st_ctime;
+
+	DAWIT_LOG_INFO(DAWIT_TAG_SSM, "File %s creation time: %ld (epoch seconds)", file_path, (long)*creation_time);
+	return DAWIT_SUCCESS;
+}
+
+dawit_result SSM_get_file_creation_time(time_t *creation_time)
+{
+	return SSM_get_file_creation_time_imp(SSM_STORED_LOGS_FILE, creation_time);
+}
+static dawit_result SSM_write_logs_to_file(void)
+{
+	ssm_file *file = NULL;
+	dawit_result result = DAWIT_SUCCESS;
+
+
+	result = SSM_file_open(&file, SSM_STORED_LOGS_TEMP_FILE, "w");
+	if (result != DAWIT_SUCCESS)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to open %s file for writing", SSM_STORED_LOGS_FILE);
+		g_ssm_file_write_context.completed = true;
+		g_ssm_file_write_context.result = DAWIT_FAIL;
+		dawit_semaphore_release(&g_ssm_file_write_context.completion_sem);
+		return DAWIT_FAIL;
+	}
+
+	/* Write ES logs */
+	result =  SSM_write_ES_logs_to_file(file);
+	if( result != DAWIT_SUCCESS)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to Write ES logs to file ");
+		SSM_file_close(file);
+		g_ssm_file_write_context.completed = true;
+		g_ssm_file_write_context.result = DAWIT_FAIL;
+		dawit_semaphore_release(&g_ssm_file_write_context.completion_sem);
+		return DAWIT_FAIL;
+	}
+
+	result =  SSM_write_SYS_logs_to_file(file);
+	if( result != DAWIT_SUCCESS)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to Write SYS logs to file ");
+		SSM_file_close(file);
+		g_ssm_file_write_context.completed = true;
+		g_ssm_file_write_context.result = DAWIT_FAIL;
+		dawit_semaphore_release(&g_ssm_file_write_context.completion_sem);
+		return DAWIT_FAIL;
+	}
+
+	/* Close the file */
+	SSM_file_close(file);
+
+	if (SSM_check_stored_logs_file_exist() == DAWIT_SUCCESS)
+	{
+		if (SSM_delete_stored_logs_file() != DAWIT_SUCCESS)
+		{
+			DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Unable to delete old ssm logs file");
+			g_ssm_file_write_context.completed = true;
+			g_ssm_file_write_context.result = DAWIT_FAIL;
+			dawit_semaphore_release(&g_ssm_file_write_context.completion_sem);
+			return DAWIT_FAIL;
+		}
+	}
+
+	SSM_rename_file(SSM_STORED_LOGS_TEMP_FILE, SSM_STORED_LOGS_FILE);
+	g_ssm_file_write_context.completed = true;
+	g_ssm_file_write_context.result = DAWIT_SUCCESS;
+	dawit_semaphore_release(&g_ssm_file_write_context.completion_sem);
+
+	DAWIT_LOG_INFO(DAWIT_TAG_SSM, "Successfully stored logs and KPI data to %s file", SSM_STORED_LOGS_FILE);
+	return DAWIT_SUCCESS;
+}
+
+dawit_result SSM_store_logs_to_file_impl(unsigned int time_limit_ms)
+{
+	dawit_result final_result = DAWIT_FAIL;
+
+	g_ssm_file_write_context.result = DAWIT_FAIL;
+	g_ssm_file_write_context.completed = false;
+
+	if (g_ssm_is_file_write_api_done)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "SSM store to file is already called");
+		return DAWIT_FAIL;
+	}
+
+	if (time_limit_ms < 1000)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Invalid time_limit [%u] >= 1000", time_limit_ms);
+		return DAWIT_INVALID_ARGS;
+	}
+
+	int ssm_es_time = SSM_get_es_interval_time();
+	int ssm_sys_time = SSM_get_sys_interval_time();
+	
+	//delay sending of ES,SYS logs
+	ssm_es_time += 30; 
+	ssm_sys_time += 30;
+
+	SSM_set_interval(SSM_EASYSETUP, ssm_es_time);
+	SSM_set_interval(SSM_SYSTEM, ssm_sys_time);
+	
+	dawit_result sem_result = dawit_semaphore_create(&g_ssm_file_write_context.completion_sem, 0);
+	if (sem_result != DAWIT_SUCCESS) {
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to create completion semaphore");
+		return DAWIT_FAIL;
+	}
+
+	dawit_task worker_task = 1;
+	dawit_result task_result = dawit_task_create((dawit_task*)&worker_task, "SSM_file_write_worker", 
+	                                (void*)SSM_write_logs_to_file, NULL,
+	                                DAWIT_NORMAL_PRIORITY, 1024*6);
+	if (task_result != DAWIT_SUCCESS) {
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to create SSM file write thread");
+		dawit_semaphore_destroy(&g_ssm_file_write_context.completion_sem);
+		return DAWIT_FAIL;
+	}
+
+	sem_result = dawit_semaphore_acquire(&g_ssm_file_write_context.completion_sem, time_limit_ms);
+	
+	if (sem_result == DAWIT_TIMEOUT)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "File write operation timed out after [%d] ms, ending SSM file write", time_limit_ms);
+		
+		SSM_set_file_write_timeout(true);
+		final_result = DAWIT_TIMEOUT;
+	}
+	else if (sem_result == DAWIT_SUCCESS)
+	{
+		/* Operation completed within timeout - get the result */
+		final_result = g_ssm_file_write_context.result;
+
+		if (g_ssm_file_write_context.completed)
+		{
+			if (g_ssm_file_write_context.result == DAWIT_SUCCESS)
+			{
+				DAWIT_LOG_INFO(DAWIT_TAG_SSM, "Success to write SSM logs into file");
+			}
+			else
+			{
+				DAWIT_LOG_INFO(DAWIT_TAG_SSM, "Failed to write SSM logs into file internal failure");
+			}
+		}
+	}
+	else
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Semaphore acquire failed");
+		final_result = DAWIT_FAIL;
+	}
+
+	DAWIT_LOG_DEBUG(DAWIT_TAG_SSM, "SSM write function end");
+	g_ssm_is_file_write_api_done = true;
+	return final_result;
+}
+
+/* Skip characters until newline is found */
+static void SSM_skip_to_next_line(ssm_file *file)
+{
+	unsigned char ch;
+	while (SSM_file_read(file, &ch, 1) == DAWIT_SUCCESS)
+	{
+		if (ch == '\n')
+		{
+			break;
+		}
+	}
+}
+
+/* Read one ES log record from file directly into a log_data node.
+ * Reads character by character, no intermediate line buffer needed.
+ * Returns log_data node on success, NULL if non-ES/invalid/EOF.
+ * *is_eof is set to true when end of file is reached. */
+static log_data* SSM_read_ES_log_from_file(ssm_file *file, bool *is_eof)
+{
+	unsigned char ch;
+	int field = 0;  /* 0=type, 1=time, 2=code, 3=message */
+	int type_value = 0;
+	int time_value = 0;
+	char code_value[LOG_BUFFER_CODE_SIZE] = {0};
+	int code_pos = 0;
+	char *message_buf = NULL;
+	int message_pos = 0;
+	int message_size = 0;
+	dawit_result read_result = DAWIT_SUCCESS;
+
+	if (is_eof != NULL)
+	{
+		*is_eof = false;
+	}
+
+	/* Look for start of record '<' */
+	ch = '\0';
+	while ((read_result = SSM_file_read(file, &ch, 1)) == DAWIT_SUCCESS)
+	{
+		if (ch == '<')
+		{
+			break;
+		}
+		/* Skip anything before '<' (including newlines) */
+	}
+
+	/* If we couldn't read, it's EOF */
+	if (ch != '<')
+	{
+		if (is_eof != NULL) *is_eof = true;
+		DAWIT_LOG_DEBUG(DAWIT_TAG_SSM, "SSM ES file read EOF");
+		return NULL;
+	}
+
+	/* Parse fields character by character */
+	while ((read_result = SSM_file_read(file, &ch, 1)) == DAWIT_SUCCESS)
+	{
+		if (ch == '>')
+		{
+			/* End of record - consume trailing newline if present */
+			unsigned char next_ch;
+			if (SSM_file_read(file, &next_ch, 1) == DAWIT_SUCCESS && next_ch != '\n')
+			{
+				/* Not a newline, continue reading */
+				SSM_file_seek(file, -1, SEEK_CUR); /* Put the character back */
+			}
+
+			/* Null terminate message */
+			if (message_buf != NULL)
+			{
+				message_buf[message_pos] = '\0';
+			}
+
+			/* Only create node for ES records (type 0) with valid code */
+			if (type_value != 0 || code_pos == 0)
+			{
+				free(message_buf);
+				if (is_eof != NULL) *is_eof = true;
+				DAWIT_LOG_DEBUG(DAWIT_TAG_SSM, "SSM ES file read EOF");
+				return NULL;
+			}
+
+			log_data *new_node = (log_data *)calloc(1, sizeof(log_data));
+			if (new_node == NULL)
+			{
+				DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to allocate memory for log_data node");
+				free(message_buf);
+				return NULL;
+			}
+
+			new_node->time = time_value;
+			snprintf(new_node->code, LOG_BUFFER_CODE_SIZE, "%s", code_value);
+			new_node->message = message_buf;
+			new_node->level = 5;
+			new_node->pre = NULL;
+			new_node->next = NULL;
+			return new_node;
+		}
+
+		if (ch == '#')
+		{
+			field++;
+			continue;
+		}
+
+		switch (field)
+		{
+			case 0: /* Type */
+				if (ch >= '0' && ch <= '9')
+				{
+					type_value = type_value * 10 + (ch - '0');
+				}
+				break;
+			case 1: /* Time */
+				if (ch >= '0' && ch <= '9')
+				{
+					time_value = time_value * 10 + (ch - '0');
+				}
+				break;
+			case 2: /* Code */
+				if (code_pos < LOG_BUFFER_CODE_SIZE - 1)
+				{
+					code_value[code_pos++] = ch;
+				}
+				break;
+			case 3: /* Message - dynamically grow buffer */
+				if (message_pos >= message_size - 1)
+				{
+					message_size += 64;
+					char *new_buf = (char *)realloc(message_buf, message_size);
+					if (new_buf == NULL)
+					{
+						DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to allocate memory for message");
+						free(message_buf);
+						SSM_skip_to_next_line(file);
+						return NULL;
+					}
+					message_buf = new_buf;
+				}
+				message_buf[message_pos++] = ch;
+				break;
+		}
+	}
+
+	/* EOF reached before completing record */
+	if (is_eof != NULL) *is_eof = true;
+	free(message_buf);
+	return NULL;
+}
+
+/* Append a log_data node to the doubly linked list */
+static void SSM_append_log_to_list(log_data **head, log_data **tail, log_data *new_node)
+{
+	if (new_node == NULL)
+	{
+		return;
+	}
+
+	if (*head == NULL)
+	{
+		*head = new_node;
+		*tail = new_node;
+	}
+	else
+	{
+		(*tail)->next = new_node;
+		new_node->pre = *tail;
+		*tail = new_node;
+	}
+}
+
+/* Read up to SSM_MAX_ES_LOG_READ_LINES ES log records from an already-open file.
+ * Returns linked list of log_data. Sets *is_eof to true when file ends. */
+static log_data* SSM_read_ES_logs_batch(ssm_file *file, bool *is_eof)
+{
+	log_data *head = NULL;
+	log_data *tail = NULL;
+	int es_count = 0;
+
+	/* Read records directly into linked list, up to SSM_MAX_ES_LOG_READ_LINES ES records */
+	while (es_count < SSM_MAX_ES_LOG_READ_LINES && !(*is_eof))
+	{
+		log_data *new_node = SSM_read_ES_log_from_file(file, is_eof);
+		if (new_node != NULL)
+		{
+			SSM_append_log_to_list(&head, &tail, new_node);
+			es_count++;
+		}
+		/* NULL means non-ES record, invalid line, or EOF - continue until es_count reached or EOF */
+	}
+
+	DAWIT_LOG_INFO(DAWIT_TAG_SSM, "Read batch of %d ES log records", es_count);
+	return head;
+}
+
+/* Read one SYS log record from file and store in file data table.
+ * Returns 1 on success (SYS record saved), 0 if non-SYS/invalid record, -1 on EOF. */
+static int SSM_read_and_restore_SYS_log(ssm_file *file, bool *is_eof)
+{
+    unsigned char ch;
+    int field = 0;  /* 0=type, 1=kpi_name, 2=data_type, 3=message */
+    int type_value = 0;
+    char *kpi_name_buf = NULL;
+    int kpi_name_pos = 0;
+    int kpi_name_size = 0;
+    char data_type_buf[8] = {0};
+    int data_type_pos = 0;
+    char *message_buf = NULL;
+    int message_pos = 0;
+    int message_size = 0;
+
+    if (is_eof != NULL) *is_eof = false;
+
+    /* Look for start of record '<' */
+    ch = '\0';
+    while (SSM_file_read(file, &ch, 1) == DAWIT_SUCCESS)
+    {
+        if (ch == '<') break;
+    }
+
+    if (ch != '<')
+    {
+        if (is_eof != NULL) *is_eof = true;
+        return -1;
+    }
+
+    /* Parse fields character by character */
+    while (SSM_file_read(file, &ch, 1) == DAWIT_SUCCESS)
+    {
+        if (ch == '>')
+        {
+            /* Consume trailing newline if present */
+            unsigned char next_ch;
+            if (SSM_file_read(file, &next_ch, 1) == DAWIT_SUCCESS && next_ch != '\n')
+            {
+                /* Not a newline, continue reading */
+                SSM_file_seek(file, -1, SEEK_CUR); /* Put the character back */
+            }
+
+            /* Null terminate buffers */
+            if (kpi_name_buf != NULL) kpi_name_buf[kpi_name_pos] = '\0';
+            if (message_buf != NULL) message_buf[message_pos] = '\0';
+
+            /* Only process SYS records (type 1) with valid kpi_name */
+            if (type_value != 1 || kpi_name_pos == 0)
+            {
+                free(kpi_name_buf);
+                free(message_buf);
+                return 0;
+            }
+
+            /* Check if we have space in the file data table */
+            if (kpi_file_count >= KPI_BUFFER_SIZE) {
+                DAWIT_LOG_WARNING(DAWIT_TAG_SSM, "KPI file data table is full, discarding entry");
+                free(kpi_name_buf);
+                free(message_buf);
+                return 0;
+            }
+
+            /* Store data in file data table */
+            kpi_file_table[kpi_file_count].kpi_name = kpi_name_buf;
+            snprintf(kpi_file_table[kpi_file_count].data_type, 
+                sizeof(kpi_file_table[kpi_file_count].data_type), "%s", data_type_buf);
+            kpi_file_table[kpi_file_count].kpi_message = message_buf;
+
+            DAWIT_LOG_INFO(DAWIT_TAG_SSM, "Stored in file data table: name=%s, type=%s, message=%s",
+                kpi_file_table[kpi_file_count].kpi_name,
+                kpi_file_table[kpi_file_count].data_type,
+                kpi_file_table[kpi_file_count].kpi_message ? 
+                kpi_file_table[kpi_file_count].kpi_message : "");
+
+            kpi_file_count++;
+            return 1;
+        }
+
+        if (ch == '#')
+        {
+            field++;
+            continue;
+        }
+
+        switch (field)
+        {
+            case 0: /* Type */
+                if (ch >= '0' && ch <= '9') type_value = type_value * 10 + (ch - '0');
+                break;
+            case 1: /* KPI name */
+                if (kpi_name_pos >= kpi_name_size - 1)
+                {
+                    kpi_name_size += 64;
+                    char *new_buf = (char *)realloc(kpi_name_buf, kpi_name_size);
+                    if (new_buf == NULL)
+                    {
+                        DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to allocate memory for KPI name");
+                        free(kpi_name_buf);
+                        free(message_buf);
+                        SSM_skip_to_next_line(file);
+                        return 0;
+                    }
+                    kpi_name_buf = new_buf;
+                }
+                kpi_name_buf[kpi_name_pos++] = ch;
+                break;
+            case 2: /* Data type string */
+                if (data_type_pos < (int)sizeof(data_type_buf) - 1) data_type_buf[data_type_pos++] = ch;
+                break;
+            case 3: /* Message */
+                if (message_pos >= message_size - 1)
+                {
+                    message_size += 64;
+                    char *new_buf = (char *)realloc(message_buf, message_size);
+                    if (new_buf == NULL)
+                    {
+                        DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to allocate memory for message");
+                        free(kpi_name_buf);
+                        free(message_buf);
+                        SSM_skip_to_next_line(file);
+                        return 0;
+                    }
+                    message_buf = new_buf;
+                }
+                message_buf[message_pos++] = ch;
+                break;
+        }
+    }
+
+    /* EOF reached before completing record */
+    if (is_eof != NULL) *is_eof = true;
+    free(kpi_name_buf);
+    free(message_buf);
+    return -1;
+}
+
+
+/* Read up to SSM_MAX_SYS_LOG_READ_LINES SYS log records from file and
+ * directly save them to KPI_buffer_table_array (no linked list needed).
+ * Returns the number of SYS records restored in this batch. */
+static int SSM_restore_SYS_logs_batch(ssm_file *file, bool *is_eof)
+{
+	int sys_count = 0;
+
+	while (sys_count < SSM_MAX_SYS_LOG_READ_LINES && !(*is_eof))
+	{
+		int result = SSM_read_and_restore_SYS_log(file, is_eof);
+		if (result == 1)
+		{
+			sys_count++;
+		}
+		/* result == 0: non-SYS record or invalid, continue */
+		/* result == -1: EOF, loop will exit */
+	}
+
+	DAWIT_LOG_INFO(DAWIT_TAG_SSM, "Restored batch of %d SYS log records to KPI buffer", sys_count);
+	return sys_count;
+}
+
+/* Restore ES log records from file-read linked list into log_buffer,
+ * then call SSM_Send_ES_log_protected() which reads from log_buffer to send. */
+static dawit_result SSM_restore_and_send_ES_logs(log_data *head)
+{
+	if (head == NULL)
+	{
+		DAWIT_LOG_INFO(DAWIT_TAG_SSM, "No ES logs to restore");
+		return DAWIT_FAIL;
+	}
+
+	dawit_result result = SSM_Send_ES_logs_from_file((void *)head);
+	if (result == DAWIT_SUCCESS)
+	{
+		DAWIT_LOG_INFO(DAWIT_TAG_SSM, "ES logs sent to server successfully");
+	}
+	else
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to send ES logs to server");
+	}
+
+	return result;
+}
+
+
+/* Free the linked list of log_data */
+static void SSM_free_log_data_list(log_data *head)
+{
+	log_data *current = head;
+	log_data *next_node = NULL;
+
+	while (current != NULL)
+	{
+		next_node = current->next;
+		if (current->message != NULL)
+		{
+			free(current->message);
+		}
+		free(current);
+		current = next_node;
+	}
+}
+
+dawit_result SSM_check_stored_logs_file_exist(void)
+{
+	return SSM_file_is_exist((char *)SSM_STORED_LOGS_FILE);
+}
+
+dawit_result SSM_delete_stored_logs_file(void)
+{
+	return SSM_file_delete((char *)SSM_STORED_LOGS_FILE);
+}
+
+dawit_result SSM_read_logs_from_file_and_send_impl(void)
+{
+	ssm_file *file = NULL;
+	bool is_eof = false;
+	int es_batch_num = 0;
+	int sys_batch_num = 0;
+	int total_es_count = 0;
+	int total_sys_count = 0;
+	dawit_result result = DAWIT_SUCCESS;
+	
+    if (SSM_is_policy_done() != DAWIT_TRUE)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "SSM policy is not yet loaded");
+		return DAWIT_FAIL;
+	}
+	/* Open file for reading */
+	result = SSM_file_open(&file, SSM_STORED_LOGS_FILE, "r");
+	if (result != DAWIT_SUCCESS)
+	{
+		DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to open %s file for reading", SSM_STORED_LOGS_FILE);
+		return DAWIT_FAIL;
+	}
+
+	/* Read ES records in batches of 20, print each batch, until file ends */
+	DAWIT_LOG_INFO(DAWIT_TAG_SSM, "=== Reading ES Records ===");
+	while (!is_eof)
+	{
+		log_data *log_list = SSM_read_ES_logs_batch(file, &is_eof);
+
+		if (log_list == NULL)
+		{
+			break;
+		}
+
+		es_batch_num++;
+		DAWIT_LOG_INFO(DAWIT_TAG_SSM, "=== ES Batch [%d] ===", es_batch_num);
+
+		log_data *current = log_list;
+		while (current != NULL)
+		{
+			total_es_count++;
+			current = current->next;
+		}
+
+		/* Restore ES logs to buffer and send to server */
+		SSM_restore_and_send_ES_logs(log_list);
+
+		SSM_free_log_data_list(log_list);
+	}
+
+	/* SYS records are at end of file, continue reading from current position */
+	is_eof = false;
+
+	/* Read SYS records in batches of 50 and save directly to KPI_buffer_table_array */
+	DAWIT_LOG_INFO(DAWIT_TAG_SSM, "=== Reading SYS Records ===");
+	while (!is_eof)
+	{
+		int batch_count = SSM_restore_SYS_logs_batch(file, &is_eof);
+
+		if (batch_count == 0)
+		{
+			break;
+		}
+
+		sys_batch_num++;
+		DAWIT_LOG_INFO(DAWIT_TAG_SSM, "=== SYS Batch [%d] ===", sys_batch_num);
+
+		total_sys_count += batch_count;
+	}
+
+	SSM_file_close(file);
+
+	/* Send all SYS logs from KPI buffer to server (after all batches are restored) */
+	if (total_sys_count > 0)
+	{
+
+		dawit_result sys_result = SSM_Send_SYS_logs_from_file(kpi_file_table, kpi_file_count);
+		if (sys_result == DAWIT_SUCCESS)
+		{
+			DAWIT_LOG_INFO(DAWIT_TAG_SSM, "SYS logs sent to server successfully");
+		}
+		else
+		{
+			DAWIT_LOG_ERROR(DAWIT_TAG_SSM, "Failed to send SYS logs to server");
+		}
+
+		SSM_free_sys_kpi_table();
+	}
+
+	DAWIT_LOG_INFO(DAWIT_TAG_SSM, "Total [%d] ES logs in [%d] batches, [%d] SYS logs in [%d] batches",
+		total_es_count, es_batch_num, total_sys_count, sys_batch_num);
+
+	if (total_es_count == 0 && total_sys_count == 0)
+	{
+		DAWIT_LOG_INFO(DAWIT_TAG_SSM, "No logs found in file");
+		return DAWIT_FAIL;
+	}
+
+	return DAWIT_SUCCESS;
+}
+
+static void SSM_free_sys_kpi_table(void)
+{
+	for (unsigned int i = 0; i < kpi_file_count && i < KPI_BUFFER_SIZE; i++)
+    {
+        if (kpi_file_table[i].kpi_name != NULL)
+        {
+            free(kpi_file_table[i].kpi_name);
+            kpi_file_table[i].kpi_name = NULL;
+        }
+        if (kpi_file_table[i].kpi_message != NULL)
+        {
+            free(kpi_file_table[i].kpi_message);
+            kpi_file_table[i].kpi_message = NULL;
+        }
+    }
+    kpi_file_count = 0;
+}
+static SSM_Log_Type SSM_map_code_to_log_type(char code)
+{
+	switch (code)
+	{
+	case 'C':
+	case 'c':
+		return SSM_CS;
+	case 'E':
+	case 'e':
+		return SSM_ES;
+	case 'N':
+	case 'n':
+		return SSM_NS;
+	case 'A':
+	case 'a':
+		return SSM_AS;
+	case 'S':
+	case 's':
+		return SSM_SS;
+	case 'P':
+	case 'p':
+		return SSM_PS;
+	case 'R':
+	case 'r':
+		return SSM_RR;
+	default:
+		return SSM_CS; // Default to CS for unknown codes
+	}
+}
